<script setup>
import LetterBoxes from "../../Components/LetterBoxes.vue";
import VocabularyText from "../../Components/VocabularyText.vue";
import { practicePreference } from '../../lib/practice-preference.js';
import FlashcardNote from "../../Components/FlashcardNote.vue";
import StartIcon from "../../Components/StartIcon.vue";
import { swipeMark } from '../../lib/flashcard-swipe.js';
import { collectionVoicePreference } from '../../lib/speech-preference.js';
import { createStudyQueue,appendStudyRepeat,studyAttemptPayload,prioritizeGuestWords,completedGuestMastery,selectGuestStudyQuestions } from '../../lib/study-queue.js';
import { postSession, sessionAnswers } from '../../lib/session-api.js';
import { useI18n } from '../../lib/i18n.js';
import { computed,ref,onMounted,onBeforeUnmount,watch } from 'vue';
import { createLocalSpeech,localVoices,resolveLocalVoice,observeVoiceChanges } from '../../lib/speech.js';import { Head,Link,usePage } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';import { createQuestions,isCorrect,score,shouldAutoCheck } from '../../lib/study.js';
const {t}=useI18n();
const props=defineProps({collection:Object,words:{type:Array,default:()=>[]},mode:{type:String,default:'flashcards'},shared:{type:Boolean,default:false},settings:{type:Object,default:()=>({})}});
const page=usePage();
let storage;try{storage=window.localStorage;}catch{}
const setupMemory=practicePreference(storage,props.collection,page.props.auth?.user?.id??'guest',props.mode,props.shared);
const restoredSettings=setupMemory.read(props.settings,props.words.length);
const options=ref({type:restoredSettings.type,direction:restoredSettings.direction,order:restoredSettings.order,count:restoredSettings.count});
const directions=ref(restoredSettings.directions);
const answerTypes=ref(restoredSettings.types);
const practiceSettings=computed(()=>({...options.value,...(props.mode!=='flashcards'?{directions:directions.value,types:answerTypes.value}:{})}));
watch(practiceSettings,settings=>setupMemory.write(settings,props.words.length),{deep:true});
function toggleSetting(values,value){if(values.includes(value)){if(values.length>1)values.splice(values.indexOf(value),1);}else values.push(value);}
const started=ref(false),questions=ref([]),index=ref(0),flipped=ref(false),answer=ref(''),checked=ref(false),correct=ref(false),results=ref([]),finished=ref(false),practiceRound=ref(false);
const noteBusy=ref(false);
function updateWordNote(id,note){questions.value=questions.value.map(q=>q.id===id?{...q,note}:q);}
let guestCompletedRounds=0;
const attempts=ref([]),guestLearned=new Set(),guestStages=new Map(),mastery=ref([]),stopped=ref(false);
const masteryRows=computed(()=>mastery.value.map(item=>({...item,word:props.words.find(word=>word.id===item.word_id)})));
const stageLabel=item=>t(item.stage==='reinforced'?'Reinforced':item.qualified?'Learning':'Needs practice');
const sessionId=ref(null),busy=ref(false),saveState=ref(''),sessionError=ref(''),selfAssessed=ref(false);
const speechEnabled=ref(false),voices=ref([]),voiceURI=ref(''),rulesVersion=ref(3);
const voiceMemory=collectionVoicePreference(storage,props.collection,page.props.auth?.user?.id??'guest',props.shared);
let stopObservingVoices;
const synthesis=typeof window!=='undefined'?window.speechSynthesis:null;
const speech=createLocalSpeech(synthesis,typeof window!=='undefined'?window.SpeechSynthesisUtterance:null);
const speechAvailable=computed(()=>speech.supported&&voices.value.length>0);
function refreshVoices(){
 voices.value=localVoices(synthesis);
 const rememberedVoice=voiceMemory.read();
 const selected=resolveLocalVoice(voices.value,rememberedVoice);
 if(!selected){voiceURI.value='';speechEnabled.value=false;speech.cancel();}
 else voiceURI.value=rememberedVoice;
}
function speak(text){if(speechEnabled.value&&voiceURI.value)speech.speak(text,voiceURI.value);}
function speakQuestion(){if(started.value&&!finished.value&&current.value)speak(props.mode==='flashcards'&&flipped.value?current.value.expected:current.value.prompt);}
onMounted(()=>{stopObservingVoices=observeVoiceChanges(synthesis,window,document,refreshVoices);});
onBeforeUnmount(()=>{clearTimeout(swipeTimer);stopObservingVoices?.();speech.dispose();});

watch([speechEnabled,voiceURI],()=>{speech.cancel();speakQuestion();});
watch([index,started,finished,questions,flipped],()=>{speech.cancel();speakQuestion();});
const current=computed(()=>questions.value[index.value]);
const reviewRows=computed(()=>props.mode!=='flashcards'?attempts.value:results.value);
const summary=computed(()=>score(results.value));
const modeLabel=computed(()=>({flashcards:t('Flashcards'),study:t('Study'),test:t('Test')}[props.mode]??t('Study')));
const base=computed(()=>props.shared?`/s/${props.collection.share_uuid}`:`/collections/${props.collection.id}`);
const wrong=computed(()=>results.value.filter(r=>!r.correct));
async function start(retry=false){
 if(busy.value||saveState.value==='error')return;
 busy.value=true;sessionError.value='';
 try {
  const ids=[...new Set(wrong.value.map(r=>r.id))];
  if(props.shared){rulesVersion.value=props.mode==='study'?4:3;let source=retry?props.words.filter(w=>ids.includes(w.id)):props.words;if(props.mode==='study'&&!retry){const ordered=createQuestions(source,{...practiceSettings.value,count:source.length});const preferred=prioritizeGuestWords(ordered,guestLearned);questions.value=selectGuestStudyQuestions(preferred,guestStages,options.value.count,guestCompletedRounds);}else questions.value=createQuestions(source,{...practiceSettings.value,count:retry?source.length:options.value.count});sessionId.value=null;}
  else {const data=await postSession(`${base.value}/sessions`,{mode:props.mode,settings:{...practiceSettings.value,count:retry?ids.length:options.value.count},...(retry?{word_ids:ids}:{}),practice_round:retry});questions.value=data.questions;sessionId.value=data.id;rulesVersion.value=data.rules_version??3;}
  if(props.shared&&props.mode==='study')questions.value=questions.value.map(question=>({...question,type:answerTypes.value.length===1&&answerTypes.value[0]==='choice'?'choice':question.type,prior_stage:guestStages.get(question.id)?.stage??'new',prior_qualified:guestStages.get(question.id)?.qualified??false,retry_type:answerTypes.value.includes('written')?'written':'choice'}));
  if(props.mode!=='flashcards')questions.value=createStudyQueue(questions.value);
  attempts.value=[];mastery.value=[];stopped.value=false;index.value=0;results.value=[];started.value=true;finished.value=false;practiceRound.value=retry;saveState.value='';reset();
 }catch(error){sessionError.value=t(error.message);}finally{busy.value=false;}
}
async function save(){
 if(props.shared||busy.value||saveState.value==='saved')return;
 busy.value=true;saveState.value='saving';sessionError.value='';
 try{const data=await postSession(`${base.value}/sessions/${sessionId.value}/complete`,{answers:props.mode!=='flashcards'?studyAttemptPayload(attempts.value):sessionAnswers(results.value,props.mode)});if(data.results){if(props.mode!=='flashcards')attempts.value=data.results;results.value=props.mode!=='flashcards'?data.results.filter(item=>item.first_attempt||item.attempt_no===1):data.results;}if(props.mode==='study'&&rulesVersion.value>=4)mastery.value=data.mastery??[];saveState.value='saved';}
 catch(error){saveState.value='error';sessionError.value=t(error.message);}finally{busy.value=false;}
}
function reset(){selfAssessed.value=false;flipped.value=false;answer.value='';checked.value=false;correct.value=false;}
function check(){if(!answer.value.trim()||checked.value)return;correct.value=isCorrect(answer.value,current.value.expected);checked.value=true;if(current.value.type==='written')speak(answer.value);}
function selectOption(value){if(checked.value)return;answer.value=value;if(shouldAutoCheck(props.mode,current.value.type))check();speak(value);}
function next(mark=correct.value){
 if(!current.value)return;
 const result={...current.value,answer:answer.value,correct:mark,self_assessed:selfAssessed.value};
 if(props.mode!=='flashcards'){
  attempts.value.push(result);
  if(result.attempt_no===1)results.value.push(result);
  const first=results.value.find(item=>item.id===result.id);
  questions.value=appendStudyRepeat(questions.value,current.value,mark,!first.correct,rulesVersion.value);
  if(result.attempt_no===1&&!(props.shared&&props.mode==='study'&&rulesVersion.value>=4)){if(mark)guestLearned.add(result.id);else guestLearned.delete(result.id);}
 }else results.value.push(result);
 if(index.value===questions.value.length-1){finished.value=true;if(props.shared&&props.mode==='study'&&rulesVersion.value>=4){mastery.value=completedGuestMastery(attempts.value);guestCompletedRounds++;for(const item of mastery.value){guestStages.set(item.word_id,{stage:item.stage,qualified:item.qualified,last_review:guestCompletedRounds});if(item.qualified)guestLearned.add(item.word_id);else guestLearned.delete(item.word_id);}}save();return;}
 index.value++;reset();
}
function stopStudy(){
 if(!window.confirm(t('End this study session? This unfinished attempt will not be saved.')))return;
 speech.cancel();started.value=false;finished.value=false;results.value=[];attempts.value=[];questions.value=[];sessionId.value=null;saveState.value='';stopped.value=true;reset();
}
const dragX=ref(0),dragging=ref(false),swipeLeaving=ref(false);
let swipeStart=null,suppressFlipUntil=0,swipeTimer;
const flashStyle=computed(()=>({'--swipe-x':dragX.value+'px','--swipe-turn':Math.max(-14,Math.min(14,dragX.value/14))+'deg'}));
function beginSwipe(event){if(event.pointerType!=='touch'||!event.isPrimary||swipeLeaving.value||noteBusy.value||!flipped.value)return;swipeStart={id:event.pointerId,x:event.clientX,y:event.clientY};dragging.value=true;}
function moveSwipe(event){if(!swipeStart||swipeStart.id!==event.pointerId)return;const dx=event.clientX-swipeStart.x,dy=event.clientY-swipeStart.y;if(Math.abs(dy)>20&&Math.abs(dy)>Math.abs(dx)){cancelSwipe();return;}if(Math.abs(dx)>Math.abs(dy)*1.5){dragX.value=dx;if(Math.abs(dx)>10)suppressFlipUntil=Date.now()+500;}}
function cancelSwipe(){swipeStart=null;dragging.value=false;dragX.value=0;}
function endSwipe(event){const mark=swipeMark(swipeStart,{id:event.pointerId,x:event.clientX,y:event.clientY},flipped.value);swipeStart=null;dragging.value=false;if(mark===null){dragX.value=0;return;}suppressFlipUntil=Date.now()+700;swipeLeaving.value=true;dragX.value=(mark?1:-1)*Math.max(400,window.innerWidth);swipeTimer=setTimeout(()=>{next(mark);swipeLeaving.value=false;dragX.value=0;},180);}
function flipCard(){if(!swipeLeaving.value&&Date.now()>=suppressFlipUntil)flipped.value=!flipped.value;}
function restart(){if(busy.value||saveState.value==='error')return;saveState.value='';started.value=false;finished.value=false;results.value=[];reset();}
</script>
<template><Head :title="`${modeLabel} · ${collection.title}`"/><AppLayout :title="modeLabel" :subtitle="collection.title" :shared="shared"><template #actions><Link :href="base" class="button secondary">{{ t("← Collection") }}</Link></template><div class="study-wrap"><section v-if="mode!=='flashcards'&&words.length" class="panel speech-panel"><label class="speech-toggle"><input v-model="speechEnabled" type="checkbox" role="switch" :aria-checked="speechEnabled" :disabled="!speechAvailable||!voiceURI"/><span class="speech-toggle-track" aria-hidden="true"></span><span class="read-aloud-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>{{t('Read aloud')}}</span></label><p v-if="!speechAvailable||!voiceURI" class="muted small">{{t('Choose an available local voice in collection settings to read aloud.')}} <Link :href="base">{{t('Voice settings')}}</Link></p></section><p v-if="stopped" class="notice" role="status">{{ t("Study ended. No completed session was saved.") }}</p><p v-if="sessionError" class="notice error" role="alert">{{sessionError}}</p><section v-if="!words.length" class="panel empty"><h2>{{ t("A few words first.") }}</h2><p>{{ t("This collection is empty. Add words before starting a session.") }}</p><Link :href="base" class="button">{{ t("Back to collection") }}</Link></section><section v-else-if="!started" class="panel study-settings"><span class="step-label">{{ t("MAKE IT YOURS") }}</span><h2>{{ t("How would you like to practice?") }}</h2><p class="muted">{{mode==='flashcards'?t('Turn each card over, then decide what needs another look.'):mode==='test'?t('Answer all questions, then review your results at the end.'):t('Get feedback as you go, then revisit the words that need more practice.')}}</p><p v-if="mode==='study'" class="notice">{{ t("Study revisits each word later in this session. Two correct answers build Learning; a later completed session with two correct answers and no mistakes builds Reinforced. Each word has at most three attempts. With only one word, its repeat appears immediately.") }}</p><p v-if="mode==='test'" class="notice">{{ t("Test feedback appears at the end. A repeated question can indicate an earlier mistake; this is a practice test, not a secure exam.") }}</p><form @submit.prevent="start()"><div v-if="mode!=='flashcards'" class="two-col study-switch-settings"><fieldset><legend>{{ t('Question direction') }}</legend><label v-for="item in [{value:'term',label:'Show definition → recall word'},{value:'definition',label:'Show word → recall definition'}]" :key="item.value" class="speech-toggle"><input type="checkbox" role="switch" :checked="directions.includes(item.value)" :aria-checked="directions.includes(item.value)" :disabled="directions.length===1&&directions.includes(item.value)" @change="toggleSetting(directions,item.value)"/><span class="speech-toggle-track" aria-hidden="true"></span><span>{{ t(item.label) }}</span></label></fieldset><fieldset><legend>{{ t('Answer style') }}</legend><label v-for="item in [{value:'choice',label:'Multiple choice'},{value:'written',label:'Written answer'}]" :key="item.value" class="speech-toggle"><input type="checkbox" role="switch" :checked="answerTypes.includes(item.value)" :aria-checked="answerTypes.includes(item.value)" :disabled="answerTypes.length===1&&answerTypes.includes(item.value)" @change="toggleSetting(answerTypes,item.value)"/><span class="speech-toggle-track" aria-hidden="true"></span><span>{{ t(item.label) }}</span></label></fieldset></div><div class="two-col"><label v-if="mode==='flashcards'">{{mode==='flashcards'?t('Card front'):t('Question direction')}}<select v-model="options.direction"><option value="term">{{ t("Show definition → recall word") }}</option><option value="definition">{{ t("Show word → recall definition") }}</option></select></label><label>{{ t("Order") }}<select v-model="options.order"><option value="random">{{ t("Shuffled") }}</option><option value="ordered">{{ t("Collection order") }}</option></select></label><label>{{mode==='flashcards'?t('Number of cards'):t('Number of questions')}}<input v-model.number="options.count" type="number" min="1" :max="Math.min(2000,words.length)" required/></label></div><p class="muted small" v-if="mode!=='flashcards'">{{ t("Written answers ignore letter case and extra spaces, but keep accents and punctuation. During Study, you can mark an equivalent definition correct. Tests use exact normalized matching.") }}</p><p class="muted small">{{shared?t('Guest results are not saved.'):t('Completed sessions are saved to your collection history. Incomplete sessions cannot be resumed.')}} {{shared?t('No account is required, and results are not saved to the collection owner.'):t('Leaving before completion loses this attempt.')}}</p><div class="form-actions"><button class="button" :disabled="busy">{{ t('Start {mode}', {mode:modeLabel}) }}<StartIcon/></button></div></form></section><section v-else-if="finished" class="panel results"><span class="step-label">{{practiceRound?t('ANOTHER STEP FORWARD'):t('SESSION COMPLETE')}}</span><p v-if="mode!=='flashcards'" class="muted">{{ t("First-attempt score") }}</p><div class="score-circle">{{summary.percent}}<small>{{ t("%") }}</small></div><h2>{{summary.percent===100?t('Look at you grow.'):t('Every attempt is progress.')}}</h2><p class="muted">{{mode==='flashcards'?t('{correct} of {total} cards marked known.',summary):t('{correct} of {total} answers correct.',summary)}}</p><div v-if="shared" class="notice"><p>{{ t("Guest results are temporary. Add this collection to your account to save future sessions.") }}</p><Link :href="`/s/${collection.share_uuid}/join`" class="button">{{ t("Add to my collections") }}</Link></div><p v-if="!shared" role="status">{{saveState==='saved'?t('Saved to your private collection history.'):saveState==='saving'?t('Saving results…'):t('Results have not been saved.')}}</p><button v-if="saveState==='error'" class="button" :disabled="busy" @click="save">{{ t("Retry saving") }}</button><div class="actions centered"><button v-if="wrong.length" :disabled="busy||saveState==='error'" class="button" @click="start(true)">{{ t('Practice {count} again', {count:wrong.length}) }}</button><button class="button secondary" :disabled="busy||saveState==='error'" @click="restart">{{ t("New session") }}</button></div><p v-if="mode!=='flashcards'" class="notice">{{ t("Round complete. Repetitions do not change your first-attempt score.") }}</p><section v-if="mode==='study'&&rulesVersion>=4&&masteryRows.length" class="mastery-results"><h3>{{t('Learning stages')}}</h3><p class="muted small">{{t('First-attempt percentages stay separate from learning stages. A mistake prevents reinforcement in this round; two correct answers can still build Learning.')}}</p><p v-if="shared" class="notice">{{t('Guest stages exist only on this open page. They are not saved to an account or shared with the owner.')}}</p><p v-if="masteryRows.some(item=>item.applied===false)" class="notice">{{t('Another completed session updated some stages first. These are the current saved stages.')}}</p><article v-for="item in masteryRows" :key="item.word_id" class="mastery-row"><VocabularyText :text="item.word?.term??''" :direction="item.word?.text_direction"/><span class="pill" :class="`stage-${item.qualified?item.stage:'new'}`">{{stageLabel(item)}}</span></article></section><div class="review-list"><article v-for="(item,i) in reviewRows" :key="i" class="review-item"><span :class="item.correct?'result-good':'result-bad'">{{item.correct?t('✓'):t('↻')}}</span><div><small v-if="mode!=='flashcards'">{{ t("Attempt {count}", {count:item.attempt_no}) }}</small><VocabularyText as="strong" :text="item.prompt" :direction="item.text_direction"/><VocabularyText as="p" :text="item.expected" :direction="item.text_direction"/><small v-if="mode!=='flashcards'&&!item.correct">{{ t("Your answer:") }}<VocabularyText :text="item.answer || t('(blank)')" :direction="item.text_direction"/></small></div></article></div></section><template v-else-if="current"><div v-if="mode==='study'" class="actions" style="margin-bottom:1rem"><span class="muted small">{{ t("Presentation {count}", {count:index+1}) }} · {{ t("Attempt {count}", {count:current.attempt_no}) }}</span><button type="button" class="text-button" @click="stopStudy">{{ t("End study without saving") }}</button></div><div class="study-progress"><span>{{practiceRound?t('Practice again'):modeLabel}}</span><strong>{{index+1}}{{ t("/") }}{{questions.length}}</strong></div><div class="progress-track"><div :style="{width:`${index/questions.length*100}%`}"/></div><template v-if="mode==='flashcards'"><button class="flashcard" :class="{dragging,'swipe-leaving':swipeLeaving}" :style="flashStyle" @pointerdown="beginSwipe" @pointermove="moveSwipe" @pointerup="endSwipe" @pointercancel="cancelSwipe" @click="flipCard" :aria-label="flipped?t('Show question'):t('Reveal answer')"><span v-if="dragX&&!swipeLeaving" class="swipe-badge" :class="dragX>0?'known':'learning'" aria-hidden="true">{{ t(dragX>0?'✓ I know this':'↻ Still learning') }}</span><span class="tiny-label">{{flipped?t('THE ANSWER'):current.answerKey==='term'?t('THE DEFINITION'):t('THE WORD')}}</span><VocabularyText as="strong" :text="flipped?current.expected:current.prompt" :direction="current.text_direction"/><p v-if="flipped&&!shared&&current.note" class="card-note">{{current.note}}</p><small>{{flipped?t('↶ Tap to turn back'):t('↻ Tap to reveal')}}</small></button><div class="flashcard-tools"><FlashcardNote v-if="!shared" :key="current.id" :collection-id="collection.id" :word-id="current.id" :note="current.note" @saved="updateWordNote(current.id,$event)" @busy="noteBusy=$event"><template #tools><label class="speech-toggle"><input v-model="speechEnabled" type="checkbox" role="switch" :aria-checked="speechEnabled" :disabled="!speechAvailable||!voiceURI"/><span class="speech-toggle-track" aria-hidden="true"></span><span class="read-aloud-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>{{t('Read aloud')}}</span></label></template></FlashcardNote><label v-else class="speech-toggle"><input v-model="speechEnabled" type="checkbox" role="switch" :aria-checked="speechEnabled" :disabled="!speechAvailable||!voiceURI"/><span class="speech-toggle-track" aria-hidden="true"></span><span class="read-aloud-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>{{t('Read aloud')}}</span></label></div><p v-if="!speechAvailable||!voiceURI" class="muted small">{{t('Choose an available local voice in collection settings to read aloud.')}} <Link :href="base">{{t('Voice settings')}}</Link></p><p class="muted small swipe-hint">{{ t("Reveal the answer, then swipe left for Still learning or right for I know this.") }}</p><div class="actions centered"><button class="button secondary" :disabled="!flipped||swipeLeaving||noteBusy" @click="next(false)">{{ t("↻ Still learning") }}</button><button class="button" :disabled="!flipped||swipeLeaving||noteBusy" @click="next(true)">{{ t("✓ I know this") }}</button></div></template><section v-else class="panel question-panel"><div class="question-heading">{{ t("Question") }}</div><span class="tiny-label">{{current.answerKey==='term'?t('WHICH WORD FITS?'):t('WHAT DOES THIS MEAN?')}}</span><h2><button v-if="mode!=='flashcards'&&speechEnabled&&voiceURI" type="button" class="spoken-question" :aria-label="`${t('Read question aloud')}: ${current.prompt}`" @click="speakQuestion"><VocabularyText :text="current.prompt" :direction="current.text_direction"/></button><VocabularyText v-else :text="current.prompt" :direction="current.text_direction"/></h2><form @submit.prevent="check"><p v-if="mode==='study'&&rulesVersion>=4&&current.type==='choice'&&current.options.length<2" class="notice">{{t('Only one answer is available. Add distinct words for a meaningful multiple-choice challenge.')}}</p><div v-if="current.type==='choice'" class="answer-options"><label v-for="(option,i) in current.options" :key="option" :class="['answer-option',{'study-answer-option':mode!=='flashcards',selected:answer===option,'answer-option-correct':mode==='study'&&checked&&answer===option&&correct,'answer-option-incorrect':mode==='study'&&checked&&answer===option&&!correct}] "><input type="radio" name="answer-choice" :checked="answer===option" :value="option" @change="selectOption(option)" :disabled="checked" required/><svg v-if="mode!=='flashcards'" class="answer-choice-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path v-if="mode==='study'&&checked&&answer===option&&correct" d="m7.5 12 3 3 6-6" stroke-linecap="round" stroke-linejoin="round"/><g v-else-if="mode==='study'&&checked&&answer===option&&!correct"><path d="M12 7v6" stroke-linecap="round"/><circle cx="12" cy="16.5" r=".8" fill="currentColor" stroke="none"/></g></svg><span v-else class="option-letter">{{String.fromCharCode(65+i)}}</span><VocabularyText :text="option" :direction="current.option_directions?.[i]??current.text_direction"/></label></div><LetterBoxes v-else :key="current.occurrence_id??`${index}-${current.id}`" v-model="answer" :expected="current.expected" :disabled="checked" :direction="current.text_direction"/><p v-if="current.type==='written'&&(mode!=='flashcards'?answerTypes.length===1&&answerTypes[0]==='choice':options.type==='choice')" class="muted small">{{ t("Not enough distinct options for this card, so try a written answer.") }}</p><div v-if="checked&&mode==='study'" :class="['answer-feedback',correct?'good':'needs-practice']" role="status"><strong>{{correct?t('✓ You got it.'):t('↻ One to remember.')}}</strong><VocabularyText as="p" :text="current.expected" :direction="current.text_direction"/><button v-if="!correct&&current.type==='written'&&current.answerKey==='definition'" type="button" class="text-button" @click="correct=true;selfAssessed=true">{{ t("My definition means the same thing") }}</button></div><div class="form-actions"><button v-if="!checked && !shouldAutoCheck(mode,current.type)" class="button" :disabled="!answer.trim()">{{mode==='test'?t('Submit answer →'):t('Check answer')}}</button><button v-else-if="checked" class="button" type="button" @click="next()">{{ t('Continue →') }}</button></div></form></section></template></div></AppLayout></template>

